export const meta = {
  "slug": "heroicons-camera",
  "family": "heroicons",
  "name": "camera",
  "category": "Media",
  "motion": "bounce",
  "component": "createHeroiconsCameraIcon"
};

export function createHeroiconsCameraIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
